WITH filtered_customers AS (SELECT * FROM customers WHERE city IN ('Singapore', 'New York', 'Tokyo') AND (email IS NOT NULL OR credit_limit < 13600)), summary AS (SELECT QUARTER(signup_date) AS signup_quarter, COUNT(CASE WHEN country = 'US' THEN 1 END) AS us_count, COUNT(*) AS total_count FROM filtered_customers GROUP BY QUARTER(signup_date)) SELECT * FROM summary WHERE total_count > 5 ORDER BY us_count DESC;
